// The plugin's uv never shares anything with a uv of the developer: its own
// cache, Pythons and tools under the plugin's data folder, and no uv.toml read.
// Set after the backend's variables, so they always win.
const uvIsolation = () => {
  const dir = `${DATA}/${PROVIDER}/runtimes`
  return { UV_CACHE_DIR: `${dir}/uv-cache`, UV_PYTHON_INSTALL_DIR: `${dir}/uv-python`, UV_TOOL_DIR: `${dir}/uv-tools`, UV_NO_CONFIG: "1" }
}

// A server standing in for one whose token is missing: it exits at once with a
// message telling what to do, so /mcps shows it instead of a bare failure.
const standIn = (message, disabled) => ({
  type: "local",
  command: [process.execPath, "-e", `console.error(${JSON.stringify(message)});process.exit(1)`],
  environment: { BUN_BE_BUN: "1" },
  disabled,
})

// One `config.mcp` entry from the backend as an OpenCode v2 MCP server, or null
// to leave it out. `uv` is the installed uv's path (null: not available).
//   remote + headers  client mode: the backend puts the user's credential in a
//                     header; `oauth: false` stops OpenCode's own OAuth flow.
//   remote + oauth    OAuth with a pre-registered client ({clientId, scope}).
//   remote            OpenCode drives OAuth with dynamic client registration.
//   local + package   server mode: OpenCode spawns the published package itself,
//                     the user's credential only in its environment. npm runs
//                     on the Bun embedded in OpenCode (`<opencode> x --bun`,
//                     with BUN_BE_BUN=1), PyPI with the plugin's uv: no runtime to
//                     install on the workstation.
export function mcpEntry(m, uv = null, keys = new Map()) {
  const disabled = m?.enabled === false
  const credential = credentialOf(m)
  if (credential) {
    const key = keys.get(credential.integration)
    const value = key ? credential.format.replaceAll("{key}", key) : null
    // A key typed in OpenCode wins; until there is one, a token the backend still
    // delivers (transition) is kept; with neither, the server says what to do.
    if (credential.header) {
      const headers = { ...(isStringMap(m.headers) ? m.headers : {}), ...(value ? { [credential.header]: value } : {}) }
      if (!headers[credential.header]) return missingTokenServer(credential, disabled)
      m = { ...m, headers }
    } else {
      const environment = { ...(isStringMap(m.environment) ? m.environment : {}), ...(value ? { [credential.env]: value } : {}) }
      if (!environment[credential.env]) return missingTokenServer(credential, disabled)
      m = { ...m, environment }
    }
  }
  if (m?.type === "remote" && typeof m.url === "string" && m.url) {
    if (isStringMap(m.headers)) return { type: "remote", url: m.url, headers: m.headers, oauth: false, disabled }
    if (m.oauth && typeof m.oauth === "object" && typeof m.oauth.clientId === "string") {
      const oauth = { clientId: m.oauth.clientId, ...(typeof m.oauth.scope === "string" ? { scope: m.oauth.scope } : {}) }
      return { type: "remote", url: m.url, oauth, disabled }
    }
    return { type: "remote", url: m.url, disabled }
  }
  if (m?.type !== "local") return null
  const pkg = m.package
  const args = isStringList(m.args) ? m.args : []
  const environment = isStringMap(m.environment) ? m.environment : {}
  if (typeof pkg?.name !== "string" || !pkg.name || typeof pkg.version !== "string" || !pkg.version) return null
  let launch
  if (pkg.registry === "npm") {
    // --bun: without it, bun x honours the package's `#!/usr/bin/env node` and
    // runs it on whatever Node the workstation has, if any. Always OpenCode's Bun.
    launch = { command: [process.execPath, "x", "--bun", `${pkg.name}@${pkg.version}`, ...args], environment: { ...environment, BUN_BE_BUN: "1" } }
  } else if (pkg.registry === "pypi" && uv) {
    launch = { command: [uv, "tool", "run", `${pkg.name}==${pkg.version}`, ...args], environment: { ...environment, ...uvIsolation() } }
  } else if (pkg.registry === "pypi") {
    // uv could not be downloaded: say so in /mcps rather than leave the tool out silently.
    return standIn(`${pkg.name}: uv, which runs this Python tool, could not be downloaded. Check the network or the proxy, then restart OpenCode.`, disabled)
  } else {
    return null // unknown registry: fail closed
  }
  const startup = Number(m.startup_timeout_ms)
  return { type: "local", ...launch, disabled, ...(startup > 0 ? { timeout: { startup } } : {}) }
}

// allowed_tools per MCP server: OpenCode names an MCP tool `<server>_<tool>`.
// Exact match, so `tracker` never takes the tools of `tracker_admin`. An empty or
// missing list means no restriction. Returns the tool ids to remove.
export function disallowedTools(mcp, tools) {
  const rules = Object.entries(mcp ?? {})
    .filter(([, m]) => isStringList(m?.allowed_tools) && m.allowed_tools.length)
    .map(([server, m]) => ({ server, allowed: new Set(m.allowed_tools) }))
  if (!rules.length) return []
  return tools
    .filter((tool) => {
      const rule = rules.find((r) => tool.id === `${r.server}_${tool.name}`)
      return rule && !rule.allowed.has(tool.name)
    })
    .map((tool) => tool.id)
}

//----------------------------------------------
//     PERSONAL ACCESS TOKENS OF THE TOOLS
//----------------------------------------------

// A personal access token the developer types in OpenCode: the backend describes
// it, never sends it. `credential` on a config.mcp entry:
//   {integration: "acme-tracker", label: "Tracker Acme", prompt: "Personal access token",
//    inject: {header: "Authorization" | env: "TRACKER_TOKEN", format: "Bearer {key}"},
//    check: {url: "https://tracker.example/api/token/self"}}
// The plugin declares one OpenCode integration per credential (connected with
// /connect), reads its key and injects it into the server. The key never leaves
// the workstation; OpenCode keeps it in its own store (opencode.db, in clear).
const INTEGRATION_ID = /^[a-z0-9][a-z0-9-]{0,63}$/
const HEADER_NAME = /^[A-Za-z0-9-]{1,64}$/
const ENV_NAME = /^[A-Za-z_][A-Za-z0-9_]{0,63}$/

export function credentialOf(m) {
  const c = m?.credential
  if (!isObject(c) || typeof c.integration !== "string" || !INTEGRATION_ID.test(c.integration) || c.integration === PROVIDER) return null
  const inject = isObject(c.inject) ? c.inject : {}
  const format = typeof inject.format === "string" && inject.format.includes("{key}") ? inject.format : "{key}"
  const header = typeof inject.header === "string" && HEADER_NAME.test(inject.header) ? inject.header : null
  const env = typeof inject.env === "string" && ENV_NAME.test(inject.env) ? inject.env : null
  if ((m.type === "remote" && !header) || (m.type === "local" && !env)) return null
  const check = isObject(c.check) && typeof c.check.url === "string" && /^https:\/\//.test(c.check.url) ? { url: c.check.url } : null
  return {
    integration: c.integration,
    label: typeof c.label === "string" && c.label ? c.label.slice(0, 100) : c.integration,
    prompt: typeof c.prompt === "string" && c.prompt ? c.prompt.slice(0, 200) : "Personal access token",
    header,
    env,
    format,
    check,
  }
}

// Every credential the delivered config asks for, by integration id.
export function deliveredCredentials(mcp) {
  const credentials = new Map()
  for (const m of Object.values(isObject(mcp) ? mcp : {})) {
    const c = credentialOf(m)
    if (c) credentials.set(c.integration, c)
  }
  return credentials
}

