// Coalesces a burst of status changes (every server settles at startup) into one report.
function scheduleReport(ctx, state) {
  if (state.reportTimer) return
  state.reportTimer = setTimeout(() => {
    state.reportTimer = null
    reportStatus(ctx, state)
  }, Number(process.env.OIDC_STATUS_DELAY_MS ?? 1_000))
  state.reportTimer.unref?.()
}

