//            RESYNC AND LOGIN WATCH
//----------------------------------------------

// What a resync compares: a change of models, MCP servers, instructions or
// skills, or uv becoming available, reloads the running service.
const deliveredSignature = (state) =>
  JSON.stringify([
    state.delivered?.config ?? null,
    (Array.isArray(state.delivered?.skills) ? state.delivered.skills : []).map((s) => [s?.name, s?.version]),
    deliveredRules(state.delivered),
    deliveredAgents(state.delivered),
    [...(state.keys ?? new Map())].map(([id, key]) => [id, tokenKey(key)]),
    state.uv,
  ])

// Re-reads the backend config every `resync_seconds` (60 by default, 5 at
// least) and reloads providers, MCP servers and skills when it changed: a tool
// an admin adds or removes reaches the running service without a restart, and
// a removed one stops (revocation). One loop per service, whatever the number
// of locations (OpenCode runs setup() once per open folder, and for one-off CLI
// commands): each tick reads the backend once per connection and serves every
// live location; a location leaves the loop when OpenCode disposes of it.
const resync = { instances: new Set(), timer: null, every: 0, running: false }

async function resyncTick() {
  if (resync.running) return // a slow backend: never stack ticks
  resync.running = true
  try {
    const loads = new Map() // connection -> one backend call for this tick
    const load = async (ctx, previous, info) => {
      const active = await ctx.integration.connection.active(PROVIDER).catch(() => undefined)
      const key = JSON.stringify(active ?? null)
      if (!loads.has(key)) {
        const shared = {}
        loads.set(key, loadV2Config(ctx, previous, shared).then((body) => ({ body, shared })))
      }
      const { body, shared } = await loads.get(key)
      Object.assign(info, shared)
      return body
    }
    for (const { ctx, state } of [...resync.instances]) {
      try {
        const before = deliveredSignature(state)
        await deliver(ctx, state, load)
        if (deliveredSignature(state) !== before) await reloadDelivered(ctx)
        scheduleReport(ctx, state)
      } catch {} // one location failing must not starve the others
    }
  } finally {
    resync.running = false
  }
}

function startResync(ctx, state) {
  const instance = { ctx, state }
  resync.instances.add(instance)
  const every = Number(process.env.OIDC_RESYNC_MS) || Math.max(5, Number(ctx.options?.resync_seconds) || 60) * 1000
  if (!resync.timer || resync.every !== every) {
    clearInterval(resync.timer)
    resync.every = every
    resync.timer = setInterval(resyncTick, every)
    resync.timer.unref?.()
  }
  return () => {
    resync.instances.delete(instance)
    clearTimeout(state.reportTimer)
    if (!resync.instances.size) {
      clearInterval(resync.timer)
      resync.timer = null
    }
  }
}

// v2's background service outlives `opencode auth login`: the credential lands
// in this process (credential.switched, core/src/credential.ts), so re-fetch
// and reload instead of waiting for a restart. mcp.status.changed schedules a
// status report. Never awaited; runs until unload.
async function watchLogin(ctx, state) {
  try {
    for await (const e of ctx.event.subscribe()) {
      if (e?.type === "mcp.status.changed") {
        scheduleReport(ctx, state)
        continue
      }
      if (e?.type !== "credential.switched" && e?.type !== "credential.updated") continue
      // A personal access token typed with /connect: inject it, without a restart.
      if (deliveredCredentials(state.delivered?.config?.mcp).has(e.data?.integrationID)) {
        try {
          await deliver(ctx, state)
          await ctx.mcp.reload()
          state.reported = null
          scheduleReport(ctx, state)
        } catch {}
        continue
      }
      if (e.data?.integrationID !== PROVIDER) continue
      state.reported = null // another key, maybe another workstation entry: report again
      try {
        await deliver(ctx, state)
        await reloadDelivered(ctx)
      } catch {} // one failed reload must not end the watch: the next login retries
    }
  } catch {} // Silent on purpose: worst case is the old behaviour (restart to pick up a login)
}

