// One file, both engines: opencode v1 reads `server` (it rejects a default export
// with an id but no server()); v2 reads `setup`.
export default {
  id: "yagnic",
  server: SsoAuth,
  async setup(ctx) {
    const { provider } = await backend(ctx.options)
    if (PROVIDER_ID.test(provider ?? "")) PROVIDER = provider

    // Last good /clients/opencode/config body for this location's credential, or
    // null, with the keys typed for its personal access tokens. Per setup(): the
    // service runs it once per location in one module instance, so a module-level
    // value let one location's empty load drop the provider everywhere at the next reload.
    const state = { delivered: null, keys: new Map(), checks: new Map(), uv: null, reported: null, rejected: null, reportTimer: null, outage: false, failingSince: null }

    // Declared before the first delivery: resolving the YAGNIC credential may call refresh().
    await ctx.integration.transform((editor) => {
      editor.update(PROVIDER, (integration) => {
        integration.name = PROVIDER
      })
      editor.method.update({
        integrationID: PROVIDER,
        method: { id: "sso-browser", type: "oauth", label: "SSO (browser)" },
        authorize: () => authorizeBrowser(ctx.options),
        refresh: (credential) => refreshCredential("sso-browser", credential, ctx.options),
      })
      editor.method.update({
        integrationID: PROVIDER,
        method: { id: "sso-device", type: "oauth", label: "SSO (device code — sign in from another browser)" },
        authorize: () => authorizeDevice(ctx.options),
        refresh: (credential) => refreshCredential("sso-device", credential, ctx.options),
      })
      // One integration per personal access token the backend asks for:
      // the developer connects it with /connect. Re-run on each reload, so a tool
      // the backend no longer delivers loses its integration.
      for (const c of deliveredCredentials(state.delivered?.config?.mcp).values()) {
        try {
          editor.update(c.integration, (integration) => {
            integration.name = c.label
          })
          editor.method.update({ integrationID: c.integration, method: { id: "key", type: "key", label: c.prompt } })
        } catch {}
      }
    })

    await deliver(ctx, state)
    // The personal access tokens are known now: declare their integrations.
    if (deliveredCredentials(state.delivered?.config?.mcp).size) {
      try {
        await ctx.integration.reload?.()
      } catch {}
    }
    try {
      await registerV2Transforms(ctx, state)
    } catch {} // Silent on purpose: a broken backend must never stop opencode starting
    watchLogin(ctx, state)
    return startResync(ctx, state) // called by opencode when the location is disposed
  },
}
